mapper.select:
SELECT  FROM tags t WHERE t.group_id = #{groupId}
AND (${where})
AND NOT EXISTS (SELECT 1 FROM recipes_to_tags rt WHERE rt.tag_id = t.id)
ORDER BY ${order}
LIMIT #{limit} OFFSET #{offset}

SELECT r.*, u.household_id FROM recipes r JOIN users u ON u.id = r.user_id
JOIN recipes_to_tags rt ON rt.recipe_id = r.id
WHERE rt.tag_id = #{id} AND r.group_id = #{groupId}
